// Telnyx's documented Call Control webhook envelope: {data: {event_type, id, payload: {...}}}.
// UNVERIFIED against a live account, same caveat as every Telnyx/Stripe integration point in this
// repo - confirm this shape (and specifically whether client_state comes back already base64-
// decoded or still encoded) once real credentials/traffic exist.
const body = $input.first().json.body || {};
const data = body.data || {};
const payload = data.payload || {};

let decodedState = {};
try {
  const raw = payload.client_state ? Buffer.from(payload.client_state, 'base64').toString('utf8') : '{}';
  decodedState = JSON.parse(raw);
} catch (e) {
  decodedState = {}; // malformed/missing client_state - treated as an unknown leg below, not thrown
}

return [{
  json: {
    eventType: data.event_type,
    callControlId: payload.call_control_id,
    role: decodedState.role || null,
    hopperEntryId: decodedState.hopperEntryId || null,
    opportunityId: decodedState.opportunityId || null,
    repId: decodedState.repId || null,
    amdResult: payload.result || null,
    hangupCause: payload.hangup_cause || null,
    recordingUrls: payload.recording_urls || payload.recording_url || null,
  },
}];
